 void previewCancel(){abort();}
 void previewReference(int id){reference.setSelectedId(id,juce::sendNotificationSync);}
 void previewManual(juce::String text){reference.setSelectedId(3,juce::sendNotificationSync);manual.setText(text,false);edited();}
 void previewMicChange(){microphone.setText("Micro distinto",false);edited();}
 bool previewAcknowledged()const{return store.isAcknowledged(key(),ch());}
 bool previewChainChecked()const{return sameChain.getToggleState();}
 void previewSameChain(){sameChain.setToggleState(true,juce::dontSendNotification);acknowledge();}
 #endif
